class ChamberClient:
    """Every capability of the chamber node, in one object.

    async with RheedClient.connect(channel, exchange) as rheed:
        meta, frame = await rheed.camera.image()
    """

    def __init__(self, channel: AbstractChannel, exchange: AbstractExchange,
                 *, timeout: float = 10.0) -> None:
        self.log = ChamberLogClient(channel, exchange, timeout=timeout)
        self.config = ChamberConfigClient(channel, exchange, timeout=timeout)
        self.mi_mode = ChamberMiModeClient(channel, exchange, timeout=timeout)
        self.camera = ChamberCameraClient(channel, exchange, timeout=timeout)

    @property
    def capabilities(self) -> dict:
        return {
            'log': self.log,
            'config': self.config,
            'mi_mode': self.mi_mode,
            'camera': self.camera,
        }

    async def start(self) -> None:
        for client in self.capabilities.values():
            await client.start()

    async def stop(self) -> None:
        for client in self.capabilities.values():
            await client.stop()

    @classmethod
    def connect(cls, channel: AbstractChannel, exchange: AbstractExchange,
                *, timeout: float = 10.0) -> '_ConnectCtx':
        return _ConnectCtx(cls(channel, exchange, timeout=timeout))


class _ConnectCtx:
    def __init__(self, client) -> None:
        self._client = client

    async def __aenter__(self):
        await self._client.start()
        return self._client

    async def __aexit__(self, *exc) -> None:
        await self._client.stop()
